async def main(args):
    p = args.params
    hc = p.get("hook_ctx") or {}
    turn = hc.get("turn_idx", -1)
    try:
        turn = int(turn)
    except (TypeError, ValueError):
        turn = -1
    return {"payload": {"action": "set_recap", "value": str(p.get("summary") or ""), "turn": turn}}
